// === Tab: mySketch ===
// gradient noiseを使って非整数ブラウン運動作ってみる
// すげぇ雲みたい

// 雲になる前の何か
// 縁のとこのふわふわどうするんだろ

// 20220123
// 256x256でループするように改良
// ポイントはfbmのところでrandomが中身ループするようにするところ

let myShader;

let seed;
let properFrameCount = 0;

let vs =
"precision mediump float;" +
"attribute vec3 aPosition;" +
"void main(void){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";

let fs =
"precision mediump float;" +
"uniform vec2 u_resolution;" +
"uniform vec2 u_mouse;" +
"uniform float u_time;" +
"uniform vec2 u_seed;" +
"const float pi = 3.14159;" +
"const vec2 r_vector = vec2(12.9898, 78.233);" +
"const float r_coeff = 43758.5453123;" +
"const int octaves = 6;" +
// 2Dランダムベクトル(-1.0～1.0)
"vec2 random2(vec2 st, float k){" +
"  vec2 v = vec2(0.0);" +
"  st = mod(st, k);" + // これによりループするようになる
//"  st = floor(st);" +
//"  st.x = mod(st.x, k);" +
//"  st.y = mod(st.y, k);" +
"  v.x = sin(dot(st, vec2(127.1, 311.7))) * r_coeff;" +
"  v.y = sin(dot(st, vec2(269.5, 183.3))) * r_coeff;" +
"  return -1.0 + 2.0 * fract(v);" + // -1.0～1.0に正規化
"}" +
// gradient noise. (-1.0～1.0)
// 各頂点からのベクトルを各頂点におけるベクトルに掛けて内積を作る。
"float dnoise(vec2 p, float k){" +
"  vec2 i = floor(p);" +
"  vec2 f = fract(p);" +
"  vec2 u = f * f * (3.0 - 2.0 * f);" +
"  vec2 p_00 = vec2(0.0, 0.0);" +
"  vec2 p_01 = vec2(0.0, 1.0);" +
"  vec2 p_10 = vec2(1.0, 0.0);" +
"  vec2 p_11 = vec2(1.0, 1.0);" +
"  float value_00 = dot(random2(i + p_00, k), f - p_00);" +
"  float value_01 = dot(random2(i + p_01, k), f - p_01);" +
"  float value_10 = dot(random2(i + p_10, k), f - p_10);" +
"  float value_11 = dot(random2(i + p_11, k), f - p_11);" +
"  return mix(mix(value_00, value_10, u.x), mix(value_01, value_11, u.x), u.y);" +
"}" +
// fbmやってみる
"float fbm(vec2 st){" +
"  float value = 0.0;" +
"  float amplitude = 0.5;" +
"  float k = 4.0;" + // ポイントはここ。ループの内容をfbmの段階に応じて
"  for(int i = 0; i < octaves; i++){" +
"    value += amplitude * dnoise(st, k);" +
"    st *= 2.0;" +
"    k *= 2.0;" + // 変化させることで上下左右をつないでいるのです
"    amplitude *= 0.5;" +
"  }" +
"  return value;" +
"}" +
// fbm_ridge
"float fbm_ridge(vec2 st){" +
"  float value = 0.0;" +
"  float amplitude = 0.5;" +
"  float k = 4.0;" +
"  for(int i = 0; i < octaves; i++){" +
"    value += abs(amplitude * dnoise(st, k));" +
"    st *= 2.0;" +
"    k *= 2.0;" +
"    amplitude *= 0.5;" +
"  }" +
"  return value;" +
"}" +
// hsbで書かれた(0.0～1.0)の数値vec3をrgbに変換する魔法のコード
"vec3 getHSB(float r, float g, float b){" +
"    vec3 c = vec3(r, g, b);" +
"    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);" +
"    rgb = rgb * rgb * (3.0 - 2.0 * rgb);" +
"    return c.z * mix(vec3(1.0), rgb, c.y);" +
"}" +
"void main(void){" +
"  vec2 p = gl_FragCoord.xy / min(u_resolution.x, u_resolution.y);" +
"  vec2 st = p + u_seed + u_time*0.1;" +
"  st *= 4.0;" +
// fbmにより-1.0～1.0の値を出してから0.0～1.0に正規化
"  float n = fbm(st) * 0.5 + 0.5;" +
"  n = n * n * (3.0 - 2.0 * n);" +
"  float sat = 1.0;" +
"  float bl = 1.0;" +
"  float hue = 0.55;" +
// skyColorはテクスチャ用なので真っ黒でお願いします
"  vec3 skyColor = getHSB(0.6, 0.60, 0.8);" +
// cloudColorは白・・
"  vec3 cloudColor = getHSB(0.0, 0.0, 1.0);" +
// 最終的な色・・
"  vec3 col;" +
// nが0.4以下の所はskyColor, 0.6以上の所はcloudColorで、間の所は
// smoothstepでblendしてみる。
"  col = skyColor + (cloudColor - skyColor) * smoothstep(0.42, 0.58, n);" +
"  gl_FragColor = vec4(col, 1.0);" +
"}";

function setup(){
  createCanvas(1112, 834, WEBGL);
  pixelDensity(1);
  angleMode(DEGREES);
  myShader = createShader(vs, fs);
  shader(myShader);
  //noLoop();
  seed = [random() * 16, random() * 16];
}

function draw(){
  myShader.setUniform("u_resolution", [width, width]);
  myShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
  myShader.setUniform("u_time", properFrameCount / 60);
  myShader.setUniform("u_seed", seed);
  quad(-1, -1, -1, 1, 1, 1, 1, -1);
  properFrameCount++;
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

